version 1.0

workflow greet_flow {
  call make_name
  call say_hello { input: name_file = make_name.name_out }
  output { File greeting = say_hello.hello_out }
}

task make_name {
  command <<<
    echo "World" > name.txt
  >>>
  output { File name_out = "name.txt" }
}

task say_hello {
  input { File name_file }
  command <<<
    sed 's/.*/Hello, &!/' ~{name_file} > hello.txt
  >>>
  output { File hello_out = "hello.txt" }
}

version 1.0

workflow tag_flow {
  Array[String] items = ["a", "b", "c"]
  scatter (x in items) {
    call tag_item { input: item = x }
  }
  call gather { input: parts = tag_item.tagged }
  output { File all = gather.combined }
}

task tag_item {
  input { String item }
  command <<<
    echo "item:~{item}" > ~{item}.txt
  >>>
  output { File tagged = "~{item}.txt" }
}

task gather {
  input { Array[File] parts }
  command <<<
    cat ~{sep=" " parts} > all.txt
  >>>
  output { File combined = "all.txt" }
}

